def solve():
    import sys
    t = int(sys.stdin.readline())
    for _ in range(t):
        n0, n1, n2 = map(int, sys.stdin.readline().split())
        total = n0 + n1 + n2
        if total == 0:
            print("0")
            continue
        length = total + 1
        s = ['0'] * length
        if n2 > 0:
            s[0] = '1'
            s[1] = '1'
            n2 -= 1
        if n0 > 0:
            s[-2] = '0'
            s[-1] = '0'
            n0 -= 1
        i = 1
        while n1 > 0 or n2 > 0 or n0 > 0:
            if i >= length - 1:
                break
            if n2 > 0:
                s[i] = '1'
                s[i+1] = '1'
                n2 -= 1
                i += 2
            elif n0 > 0:
                s[i] = '0'
                s[i+1] = '0'
                n0 -= 1
                i += 2
            else:
                if n1 > 0:
                    if s[i] == '0':
                        s[i+1] = '1'
                    else:
                        s[i+1] = '0'
                    n1 -= 1
                    i += 1
        print(''.join(s))

solve()
